-- #######################################################################################
-- AUTOGENERATED HYPR CONFIG.
-- PLEASE USE THE CONFIG PROVIDED IN THE GIT REPO /examples/hypr.conf AND EDIT IT,
-- OR EDIT THIS ONE ACCORDING TO THE WIKI INSTRUCTIONS.
-- #######################################################################################

-- This is an example Hyprland config file.
-- Refer to the wiki for more information.
-- https://wiki.hypr.land/Configuring/Configuring-Hyprland/

local terminal = "alacritty"
local fileManager = "nemo"
local menu = "wofi --show drun --gtk-dark"
-- Kept from the old config, though it was not referenced there.
local portals =
	[[sleep 1; killall xdg-desktop-portal-hyprland & killall xdg-desktop-portal & sleep 1; /usr/lib/xdg-desktop-portal-hyprland & sleep 2; /usr/lib/xdg-desktop-portal]]
local browser = "zen-browser"
local mainMod = "SUPER"

local function combo(...)
	return table.concat({ ... }, " + ")
end

-- ###############
-- ### MONITORS ###
-- ###############

-- See https://wiki.hypr.land/Configuring/Monitors/
-- main laptop monitor
hl.monitor({ output = "eDP-1", mode = "1920x1080@60.02", position = "0x0", scale = 1 })
-- Left: Dell
hl.monitor({ output = "HDMI-A-1", mode = "preferred", position = "-1920x0", scale = 1 })
-- Right: AOC
hl.monitor({ output = "DP-1", mode = "2560x1440@59.95", position = "1920x0", scale = 1 })

-- #############################
-- ### ENVIRONMENT VARIABLES ###
-- #############################

hl.env("SSH_ASKPASS", "ksshaskpass")
hl.env("SSH_ASKPASS_REQUIRE", "prefer")
hl.env("ELECTRON_OZONE_PLATFORM_HINT", "auto")
hl.env("XCURSOR_SIZE", "48")
hl.env("HYPRCURSOR_SIZE", "48")

-- ####################
-- ### AUTOSTART ###
-- ####################

hl.on("hyprland.start", function()
	hl.exec_cmd([[systemctl --user start /usr/lib/polkit-kde-authentication-agent-1]])
	hl.exec_cmd([[waybar]])
	hl.exec_cmd([[nm-applet]])
	hl.exec_cmd([[hypridle]])
	hl.exec_cmd([[dunst]])
	hl.exec_cmd([[wl-paste --type text --watch cliphist store]])
	hl.exec_cmd([[wl-paste --type image --watch cliphist store]])
	hl.exec_cmd([[hyprctl setcursor "Banana" 48]])
	hl.exec_cmd([[gsettings set org.gnome.desktop.interface cursor-theme "Banana"]])
	hl.exec_cmd([[gsettings set org.gnome.desktop.interface cursor-size 48]])
	hl.exec_cmd(terminal)
	hl.exec_cmd([[tmux setenv -g HYPRLAND_INSTANCE_SIGNATURE "$HYPRLAND_INSTANCE_SIGNATURE"]])
end)

-- #####################
-- ### LOOK AND FEEL ###
-- #####################

hl.config({
	general = {
		gaps_in = 2,
		gaps_out = 3,
		border_size = 1,
		col = {
			active_border = { colors = { "rgba(33ccffee)", "rgba(00ff99ee)" }, angle = 45 },
			inactive_border = "rgba(595959aa)",
		},
		resize_on_border = false,
		allow_tearing = false,
		layout = "dwindle",
	},
	decoration = {
		rounding = 5,
		active_opacity = 1.0,
		inactive_opacity = 1.0,
		shadow = {
			enabled = true,
			range = 4,
			render_power = 3,
			color = "rgba(1a1a1aee)",
		},
		blur = {
			enabled = true,
			size = 3,
			passes = 1,
			vibrancy = 0.1696,
		},
	},
	animations = {
		enabled = false,
	},
	misc = {
		force_default_wallpaper = 0,
		disable_hyprland_logo = true,
		col = {
			splash = 0xff000000,
		},
	},
	input = {
		kb_layout = "us,sk",
		kb_variant = "",
		kb_model = "",
		kb_options = "grp:win_space_toggle",
		kb_rules = "",
		follow_mouse = 1,
		-- sensitivity = -0.5,
		sensitivity = 0,
		touchpad = {
			natural_scroll = false,
		},
	},
})

-- Example per-device config
hl.device({
	name = "epic-mouse-v1",
	sensitivity = -0.5,
})

-- ###################
-- ### KEYBINDINGS ###
-- ###################

hl.bind(combo(mainMod, "Return"), hl.dsp.exec_cmd(terminal))
hl.bind(combo(mainMod, "B"), hl.dsp.exec_cmd(browser))
hl.bind(combo(mainMod, "Q"), hl.dsp.window.kill())
hl.bind(combo(mainMod, "SHIFT", "W"), hl.dsp.exec_cmd([[pkill waybar && hyprctl dispatch exec waybar]]))
hl.bind(combo(mainMod, "SHIFT", "M"), hl.dsp.exit())
hl.bind(combo(mainMod, "E"), hl.dsp.exec_cmd(fileManager))
hl.bind(combo(mainMod, "V"), hl.dsp.window.float({ action = "toggle" }))
hl.bind(combo(mainMod, "D"), hl.dsp.exec_cmd(menu))
hl.bind(combo(mainMod, "P"), hl.dsp.window.pseudo({ action = "toggle" }))

-- Move focus with mainMod + arrow keys
hl.bind(combo(mainMod, "left"), hl.dsp.focus({ direction = "l" }))
hl.bind(combo(mainMod, "right"), hl.dsp.focus({ direction = "r" }))
hl.bind(combo(mainMod, "up"), hl.dsp.focus({ direction = "u" }))
hl.bind(combo(mainMod, "down"), hl.dsp.focus({ direction = "d" }))

-- Move focus with mainMod + HJKL
hl.bind(combo(mainMod, "H"), hl.dsp.focus({ direction = "l" }))
hl.bind(combo(mainMod, "L"), hl.dsp.focus({ direction = "r" }))
hl.bind(combo(mainMod, "K"), hl.dsp.focus({ direction = "u" }))
hl.bind(combo(mainMod, "J"), hl.dsp.focus({ direction = "d" }))

-- Switch workspaces with mainMod + [0-9]
hl.bind(combo(mainMod, "1"), hl.dsp.focus({ workspace = 1 }))
hl.bind(combo(mainMod, "2"), hl.dsp.focus({ workspace = 2 }))
hl.bind(combo(mainMod, "3"), hl.dsp.focus({ workspace = 3 }))
hl.bind(combo(mainMod, "4"), hl.dsp.focus({ workspace = 4 }))
hl.bind(combo(mainMod, "5"), hl.dsp.focus({ workspace = 5 }))
hl.bind(combo(mainMod, "6"), hl.dsp.focus({ workspace = 6 }))
hl.bind(combo(mainMod, "7"), hl.dsp.focus({ workspace = 7 }))
hl.bind(combo(mainMod, "8"), hl.dsp.focus({ workspace = 8 }))
hl.bind(combo(mainMod, "9"), hl.dsp.focus({ workspace = 9 }))
hl.bind(combo(mainMod, "0"), hl.dsp.focus({ workspace = 10 }))

-- Move active window to a workspace with mainMod + SHIFT + [0-9]
hl.bind(combo(mainMod, "SHIFT", "1"), hl.dsp.window.move({ workspace = 1 }))
hl.bind(combo(mainMod, "SHIFT", "2"), hl.dsp.window.move({ workspace = 2 }))
hl.bind(combo(mainMod, "SHIFT", "3"), hl.dsp.window.move({ workspace = 3 }))
hl.bind(combo(mainMod, "SHIFT", "4"), hl.dsp.window.move({ workspace = 4 }))
hl.bind(combo(mainMod, "SHIFT", "5"), hl.dsp.window.move({ workspace = 5 }))
hl.bind(combo(mainMod, "SHIFT", "6"), hl.dsp.window.move({ workspace = 6 }))
hl.bind(combo(mainMod, "SHIFT", "7"), hl.dsp.window.move({ workspace = 7 }))
hl.bind(combo(mainMod, "SHIFT", "8"), hl.dsp.window.move({ workspace = 8 }))
hl.bind(combo(mainMod, "SHIFT", "9"), hl.dsp.window.move({ workspace = 9 }))
hl.bind(combo(mainMod, "SHIFT", "0"), hl.dsp.window.move({ workspace = 10 }))

-- Example special workspace (scratchpad)
hl.bind(combo(mainMod, "S"), hl.dsp.workspace.toggle_special("magic"))
hl.bind(combo(mainMod, "SHIFT", "S"), hl.dsp.window.move({ workspace = "special:magic" }))

-- Scroll through existing workspaces with mainMod + scroll
hl.bind(combo(mainMod, "mouse_down"), hl.dsp.focus({ workspace = "e+1" }))
hl.bind(combo(mainMod, "mouse_up"), hl.dsp.focus({ workspace = "e-1" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(combo(mainMod, "mouse:272"), hl.dsp.window.drag(), { mouse = true })
hl.bind(combo(mainMod, "mouse:273"), hl.dsp.window.resize(), { mouse = true })

-- Laptop multimedia keys for volume and LCD brightness
hl.bind(
	"XF86AudioRaiseVolume",
	hl.dsp.exec_cmd([[wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+]]),
	{ repeating = true, locked = true }
)
hl.bind(
	"XF86AudioLowerVolume",
	hl.dsp.exec_cmd([[wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-]]),
	{ repeating = true, locked = true }
)
hl.bind(
	"XF86AudioMute",
	hl.dsp.exec_cmd([[wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle]]),
	{ repeating = true, locked = true }
)
hl.bind(
	"XF86AudioMicMute",
	hl.dsp.exec_cmd([[wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle]]),
	{ repeating = true, locked = true }
)
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd([[brightnessctl s 10%+]]), { repeating = true, locked = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd([[brightnessctl s 10%-]]), { repeating = true, locked = true })

-- ##############################
-- ### WINDOWS AND WORKSPACES ###
-- ##############################

-- Go to next monitor
hl.bind(combo(mainMod, "CTRL", "H"), hl.dsp.workspace.move({ monitor = "l" }))
hl.bind(combo(mainMod, "CTRL", "L"), hl.dsp.workspace.move({ monitor = "r" }))
hl.bind(combo(mainMod, "CTRL", "K"), hl.dsp.workspace.move({ monitor = "+1" }))
hl.bind(combo(mainMod, "CTRL", "J"), hl.dsp.workspace.move({ monitor = "-1" }))

hl.bind(combo(mainMod, "F"), hl.dsp.window.fullscreen({ action = "toggle" }))

hl.bind(
	combo(mainMod, "SHIFT", "V"),
	hl.dsp.exec_cmd([[cliphist list | wofi --dmenu --gtk-dark | cliphist decode | wl-copy]])
)

hl.bind(combo(mainMod, "SHIFT", "X"), hl.dsp.exec_cmd([[hyprlock]]))
hl.bind("XF86PowerOff", hl.dsp.exec_cmd([[hyprlock & systemctl suspend]]))

-- See https://wiki.hypr.land/Configuring/Window-Rules/ for more
-- See https://wiki.hypr.land/Configuring/Workspace-Rules/ for workspace rules
hl.window_rule({ match = { class = "brave-browser" }, workspace = "2" })
hl.window_rule({ match = { class = "zen" }, workspace = "2" })
hl.window_rule({ match = { class = "jetbrains-idea-ce" }, workspace = "3" })
hl.window_rule({ match = { title = "client" }, workspace = "3" })
hl.window_rule({ match = { class = "DBeaver" }, workspace = "4" })
hl.window_rule({ match = { class = "ferdium" }, workspace = "7" })
hl.window_rule({ match = { class = "discord" }, workspace = "9" })
hl.window_rule({ match = { class = "vesktop" }, workspace = "9" })

-- HYPRSHOT
-- Screenshot a window
hl.bind(combo(mainMod, "PRINT"), hl.dsp.exec_cmd([[hyprshot -m window -o /tmp]]))
-- Screenshot a monitor
hl.bind("PRINT", hl.dsp.exec_cmd([[hyprshot -m output -o /tmp]]))
-- Screenshot a region
hl.bind(combo(mainMod, "SHIFT", "PRINT"), hl.dsp.exec_cmd([[hyprshot -m region -o /tmp]]))

-- hyprwhspr - Toggle mode (added by hyprwhspr setup)
-- Press once to start, press again to stop
hl.bind(
	combo(mainMod, "ALT", "D"),
	hl.dsp.exec_cmd([[/usr/lib/hyprwhspr/config/hyprland/hyprwhspr-tray.sh record]]),
	{ description = "Speech-to-text" }
)
